#define GFS_SHARED_TRACE_FACTORY_LIBRARY
#include "test_shared_trace_factory_v1.cpp"
#include "material_shared_trace_rhs.h"
namespace rhs=shared_trace_rhs;
struct Quality {R max_chi=0,mean_chi=0,energy=0,angular=0;double minJ=DBL_MAX,force_error=0,work_error=0;uint64_t invalid=0;};
static Quality quality(const st::Factory&f,const std::vector<STPoint>&points,const std::vector<STOutput>&cpu,const std::vector<STOutput>&gpu,const std::array<rhs::Vec,2>&acceleration,const STPhysics&physics,const rhs::Boundary&boundary,bool initial,int rank,int ranks,const std::string&dest){
    R cell[24][8]={};double stat[5]={0,0,DBL_MAX,0,0};uint64_t invalid=0;R maxchi=0;
    for(size_t i=0;i<points.size();i++){const auto&q=points[i];const auto&o=cpu[i];const auto&g=gpu[i];if(!o.valid||!g.valid){invalid++;continue;}const auto&t=f.triangle[q.triangle];int c=t.cell;STJet N[ST_MAX];need(st_shape(t,q,N),"RHS quality basis");R a[2]={0,0},Da[4]={};for(int j=0;j<t.n;j++)for(int d=0;d<2;d++){R value=acceleration[d][t.id[j]];a[d]+=value*N[j].v;Da[2*d]+=value*N[j].x;Da[2*d+1]+=value*N[j].y;}
        R dm=R(q.weight)*q.rho,vx=o.point.velocity[0],vy=o.point.velocity[1],X=o.point.position[0],Y=o.point.position[1];cell[c][0]+=q.weight;cell[c][2]+=o.U;cell[c][3]+=.5L*dm*(vx*vx+vy*vy);cell[c][4]+=dm*(vx*a[0]+vy*a[1])+o.Udot-o.gpower;cell[c][5]+=dm*(X*a[1]-Y*a[0])-o.gtorque;
        if(initial){R xx=q.X,yy=q.Y,z=xx*xx+yy*yy+R(physics.eps)*physics.eps,omega2=powl(z,-1.5L),omega=powl(z,-.75L),Dg[4]={-omega2+3*xx*xx*omega2/z,3*xx*yy*omega2/z,3*xx*yy*omega2/z,-omega2+3*yy*yy*omega2/z},B[4]={1.5L*xx*yy*omega/z,-omega+1.5L*yy*yy*omega/z,omega-1.5L*xx*xx*omega/z,-1.5L*xx*yy*omega/z};R*unused=Da;(void)unused;const double*V=o.point.grad_v;R exact=Dg[0]+Dg[3]-(B[0]*B[0]+2*B[1]*B[2]+B[3]*B[3]),numerical=Da[0]+Da[3]-(R(V[0])*V[0]+2*R(V[1])*V[2]+R(V[3])*V[3]);R chi=physics.gamma*fabsl(numerical-exact)/omega2;maxchi=std::max(maxchi,chi);cell[c][1]+=q.weight*chi;}
        stat[0]=std::max(stat[0],fabs(o.identity_energy)/(o.scale_energy+1e-300));stat[1]=std::max(stat[1],fabs(o.identity_angular)/(o.scale_angular+1e-300));stat[2]=std::min(stat[2],o.point.J);for(int d=0;d<2;d++)for(int j=0;j<t.n;j++){stat[3]=std::max(stat[3],fabs(o.force[d][j]-g.force[d][j]));stat[4]=std::max(stat[4],fabs(o.force[d][j]));}
    }
    MPI_Allreduce(MPI_IN_PLACE,cell,24*8,MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,&maxchi,1,MPI_LONG_DOUBLE,MPI_MAX,MPI_COMM_WORLD);double low=stat[2];MPI_Allreduce(MPI_IN_PLACE,&low,1,MPI_DOUBLE,MPI_MIN,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,stat,5,MPI_DOUBLE,MPI_MAX,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,&invalid,1,MPI_UINT64_T,MPI_SUM,MPI_COMM_WORLD);
    Quality out;out.invalid=invalid;out.minJ=low;out.max_chi=maxchi;R E=0,L=0,U=0,K=0;for(int c=0;c<24;c++){out.mean_chi=std::max(out.mean_chi,cell[c][1]/cell[c][0]);E+=cell[c][4];L+=cell[c][5];U+=cell[c][2];K+=cell[c][3];}out.energy=fabsl(E-boundary.work)/U;out.angular=fabsl(L-boundary.torque)/(2*K);out.force_error=stat[3]/stat[4];out.work_error=std::max(stat[0],stat[1]);
    if(rank==0){FILE*fout=fopen((dest+(initial?"/initial_curvature.csv":"/finite_quality.csv")).c_str(),"w");need(fout,"new shared RHS quality ledger");fprintf(fout,"cell,mean_chi,U,K,unbalanced_energy_rate,unbalanced_angular_rate\n");for(int c=0;c<24;c++)fprintf(fout,"%llu,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg\n",(unsigned long long)f.cell[c],cell[c][1]/cell[c][0],cell[c][2],cell[c][3],cell[c][4],cell[c][5]);fclose(fout);}
    return out;
}
static void evaluate(const st::Factory&f,const std::vector<STPoint>&points,const STPhysics&physics,std::vector<STOutput>&cpu,std::vector<STOutput>&gpu,double&seconds){
    cpu.resize(points.size());gpu.resize(points.size());
    #pragma omp parallel for schedule(static)
    for(size_t i=0;i<points.size();i++)cpu[i]=st_evaluate(f.triangle.data(),f.coefficient.data(),points[i],physics);
    need(st_cuda_evaluate(f.triangle.data(),f.triangle.size(),f.coefficient.data(),f.coefficient.size(),points.data(),points.size(),&physics,gpu.data(),&seconds)==0,"same shared-state CUDA stress/work evaluation");
}
int main(int argc,char**argv){
    int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);int code=2;
    try{need(argc==3,"original finite geometry packet NEW output");auto begin=std::chrono::steady_clock::now();std::string dest=argv[2];auto packet=curved::read(argv[1]);auto f=st::topology(packet,ranks);auto points=positive_points(packet,f,rank,ranks);auto raw=raw_mass(f,points,rank,ranks);st::initialise(f,packet.parameters[3],rank,ranks);rhs::Mass M(f,raw);STPhysics physics={packet.parameters[1],packet.parameters[2],packet.parameters[3],1};std::vector<STOutput>cpu,gpu;double kernel;evaluate(f,points,physics,cpu,gpu,kernel);rhs::Boundary external;auto F=rhs::forces(f,points,cpu,physics,rank,ranks,external);std::array<rhs::Vec,2> a={rhs::Vec(f.dof.size()),rhs::Vec(f.dof.size())};int iterations[2]={};R residual[2]={};
        if(rank==0){for(int d=0;d<2;d++){auto solution=rhs::solve(M,F[d]);a[d]=std::move(solution.x);iterations[d]=solution.iterations;residual[d]=solution.true_relative_residual;}}
        for(int d=0;d<2;d++)MPI_Bcast(a[d].data(),a[d].size(),MPI_LONG_DOUBLE,0,MPI_COMM_WORLD);
        auto initial=quality(f,points,cpu,gpu,a,physics,external,true,rank,ranks,dest);
        if(rank==0){FILE*out=fopen((dest+"/shared_acceleration.csv").c_str(),"w");need(out,"new shared sparse acceleration");fprintf(out,"global_id,owner,ax,ay\n");for(size_t i=0;i<f.dof.size();i++)fprintf(out,"%zu,%d,%.21Lg,%.21Lg\n",i,f.dof[i].owner,a[0][i],a[1][i]);fclose(out);checkpoint(dest+"/initial_state.bin",f,1);}
        // ONE finite h control from THIS freshly solved shared acceleration.
        // Each owner updates its coefficient once; cells receive read-only
        // views. No accepted step, IC regeneration, heat or orbit reset.
        const R h=2e-4L;std::vector<STCoefficient> next(f.coefficient.size());for(size_t i=0;i<next.size();i++)if(f.dof[i].owner==rank)for(int d=0;d<2;d++){next[i].x[d]=R(f.coefficient[i].x[d])+h*f.coefficient[i].v[d]+.5L*h*h*a[d][i];next[i].v[d]=R(f.coefficient[i].v[d])+h*a[d][i];}MPI_Allreduce(MPI_IN_PLACE,next.data(),next.size()*4,MPI_DOUBLE,MPI_SUM,MPI_COMM_WORLD);f.coefficient.swap(next);
        evaluate(f,points,physics,cpu,gpu,kernel);rhs::Boundary external2;auto F2=rhs::forces(f,points,cpu,physics,rank,ranks,external2);std::array<rhs::Vec,2> finite_a={rhs::Vec(f.dof.size()),rhs::Vec(f.dof.size())};if(rank==0)for(int d=0;d<2;d++)finite_a[d]=rhs::solve(M,F2[d]).x;for(int d=0;d<2;d++)MPI_Bcast(finite_a[d].data(),finite_a[d].size(),MPI_LONG_DOUBLE,0,MPI_COMM_WORLD);
        auto finite=quality(f,points,cpu,gpu,finite_a,physics,external2,false,rank,ranks,dest);
        if(rank==0){auto trace=traces(f,dest);bool checkpoint_pass=checkpoint_tests(dest,f);bool curvature=initial.max_chi<=.002L&&initial.mean_chi<=.001L;bool physical=!initial.invalid&&!finite.invalid&&initial.minJ>0&&finite.minJ>0&&initial.energy<1e-8L&&finite.energy<1e-8L&&initial.angular<1e-11L&&finite.angular<1e-11L&&initial.work_error<1e-11&&finite.work_error<1e-11&&initial.force_error<1e-11&&finite.force_error<1e-11&&trace.jump==0&&trace.bubble==0&&checkpoint_pass;
            printf("{\"scope\":\"same prospective shared trace space, native sparse mass/RHS and one h2e-4 finite CONTROL, not evolution\",\"MPI_ranks\":%d,\"OMP_threads\":%d,\"scalar_dofs\":%zu,\"CSR_nonzeros\":%zu,\"global_dense_Schur\":false,\"CG_iterations\":[%d,%d],\"actual_relative_equation_residual\":[%.17Lg,%.17Lg],\"initial_chi_max\":%.17Lg,\"initial_every_cell_mean_chi_max\":%.17Lg,\"old_curvature_gate_pass\":%s,\"initial_global_energy_rate_error_over_U\":%.17Lg,\"finite_global_energy_rate_error_over_U\":%.17Lg,\"initial_global_angular_error_over_2K\":%.17Lg,\"finite_global_angular_error_over_2K\":%.17Lg,\"initial_min_J\":%.17g,\"finite_min_J\":%.17g,\"initial_CPU_CUDA_force_relative_difference\":%.17g,\"finite_CPU_CUDA_force_relative_difference\":%.17g,\"finite_point_stress_work_identity_relative\":%.17g,\"finite_canonical_trace_jump\":%.17g,\"finite_bubble_trace\":%.17g,\"checkpoint_transaction_pass\":true,\"global_physical_algebra_gate_pass\":%s,\"local_hybrid_traction_and_rotation_rate_complete\":false,\"full_factory_bundle_pass\":false,\"CUDA_kernel_seconds_rank0\":%.17g,\"seconds\":%.17g}\n",ranks,omp_get_max_threads(),f.dof.size(),M.value.size(),iterations[0],iterations[1],residual[0],residual[1],initial.max_chi,initial.mean_chi,curvature?"true":"false",initial.energy,finite.energy,initial.angular,finite.angular,initial.minJ,finite.minJ,initial.force_error,finite.force_error,finite.work_error,trace.jump,trace.bubble,physical?"true":"false",kernel,std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count());code=curvature&&physical?0:2;
        }MPI_Bcast(&code,1,MPI_INT,0,MPI_COMM_WORLD);
    }catch(const std::exception&e){fprintf(stderr,"rank%d FAIL %s\n",rank,e.what());MPI_Abort(MPI_COMM_WORLD,2);}MPI_Finalize();return code;
}
